function renderNav(filter=''){nav.innerHTML='';Object.entries(registry).forEach(([groupKey,g])=>{const pages=Object.entries(g.pages||{}).filter(([key,p])=>{const hay=(key+' '+(p.title||'')+' '+(p.actions||[]).join(' ')+' '+(p.tables||[]).join(' ')).toLowerCase();return !filter||hay.includes(filter)});if(!pages.length)return;const d=document.createElement('details');d.open=true;const s=document.createElement('summary');s.textContent=(g.icon||'')+' '+(g.label||groupKey);d.appendChild(s);const sub=document.createElement('div');sub.className='sub';pages.forEach(([key,p])=>{const b=document.createElement('button');b.className='link'+(key===selected?' active':'');b.innerHTML='<span>'+esc(p.title)+'</span><small>'+esc(p.layout)+'</small>';b.onclick=()=>{selected=key;render()};sub.appendChild(b)});d.appendChild(sub);nav.appendChild(d)})}
function actionButton(key,label,cls=''){return permissions[key]?'<button class="button '+cls+' server-action" data-action="'+key+'">'+label+'</button>':'<button class="button" disabled>'+label+' (restricted)</button>'}
function commandCenter(){const c=state.colony;const progression=state.progression;const resourceTiles=Object.entries(state.resources).map(([key,value])=>'<div class="resource-tile"><small>'+esc(key.replace('_',' '))+'</small><strong>'+fmt(value)+'</strong><div class="bar"><i style="width:'+Math.min(100,Math.max(10,Math.round(Number(value)/12400)))+'%"></i></div></div>').join('');const queues=state.queues.map(q=>'<div class="row"><div><strong>'+esc(q.name)+'</strong><small>'+esc(q.kind)+' · '+esc(q.level)+' · '+esc(q.status)+'</small></div><span class="badge">'+esc(q.remaining)+'</span></div>').join('');const missions=state.missions.map(m=>'<div class="row"><div><strong>'+esc(m.type)+'</strong><small>'+esc(m.target)+' · '+esc(m.status)+'</small></div><span class="badge">'+esc(m.eta)+'</span></div>').join('');const buildings=state.buildings.map(b=>'<tr><td>'+esc(b.name)+'</td><td>Level '+b.level+'</td><td>'+esc(b.output)+'</td><td><span class="badge good">'+esc(b.state)+'</span></td></tr>').join('');const alerts=state.alerts.map(a=>'<div class="alert"><strong class="'+esc(a.level)+'">'+esc(a.title)+'</strong><span>'+esc(a.detail)+'</span></div>').join('');document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Command Center';document.getElementById('description').textContent='Server-authoritative colony operations, life support, queues, fleet movement, and turn settlement in one game dashboard.';document.getElementById('content').innerHTML='<div class="resource-strip">'+resourceTiles+'</div><div class="cc-grid"><div class="card wide"><div class="eyebrow">COLONY OVERVIEW</div><h2>'+esc(c.name)+' <span class="badge">'+esc(c.coordinate)+'</span></h2><div class="metric-grid"><div class="metric"><span>Population</span><strong>'+fmt(c.population)+' / '+fmt(c.capacity)+'</strong><small>Capacity utilization '+Math.round(c.population/c.capacity*100)+'%</small></div><div class="metric"><span>Morale</span><strong>'+c.morale+'%</strong><small>Stable colony confidence</small></div><div class="metric"><span>Life support</span><strong>'+fmt(c.food)+' / '+fmt(c.water)+'</strong><small>Food / Water reserves</small></div></div><div class="feedback" style="display:block">State loaded from <b>players</b>, <b>player_resources</b>, <b>player_colonies</b>, <b>rankings</b>, and <b>game_events</b>.</div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS</div><h2>Command controls</h2><div class="actions"><div class="action"><span>Process next turn</span>'+actionButton('process_turns','Process turns','dark')+'</div><div class="action"><span>Open target board</span>'+actionButton('choose_target','Choose target')+'</div><div class="action"><span>Read command reports</span>'+actionButton('review_reports','Review reports')+'</div></div><div class="permission">Authenticated commander · CSRF required · RBAC checked · ownership validated · transaction committed server-side.</div><div id="feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">CONSTRUCTION / RESEARCH / SHIPYARD</div><h2>Active queues</h2>'+queues+'</div><div class="card side-card"><div class="eyebrow">LIFE SUPPORT</div><h2>Colony systems</h2><div class="row"><div><strong>Food</strong><small>'+c.food_rate+' / hour consumption</small></div><span class="badge good">NOMINAL</span></div><div class="row"><div><strong>Water</strong><small>'+c.water_rate+' / hour consumption</small></div><span class="badge good">NOMINAL</span></div><div class="row"><div><strong>Morale</strong><small>Population stability</small></div><span class="badge good">'+c.morale+'%</span></div>'+actionButton('open_colony','Open colony')+'</div><div class="card wide"><div class="eyebrow">BUILDING STATUS</div><h2>Colony infrastructure</h2><table class="table"><thead><tr><th>Building</th><th>Level</th><th>Output</th><th>State</th></tr></thead><tbody>'+buildings+'</tbody></table></div><div class="card side-card"><div class="eyebrow">FLEET CONTROL</div><h2>Mission board</h2>'+missions+actionButton('dispatch_fleet','Dispatch fleet')+'</div><div class="card wide"><div class="eyebrow">UNIVERSAL PROGRESSION</div><h2>Tier '+progression.tier+' / Level '+progression.level+' <span class="badge">'+esc(progression.tier_name)+'</span></h2><div class="metric-grid"><div class="metric"><span>Global level</span><strong>'+progression.global_level+' / 483</strong><small>21 tiers × 23 levels</small></div><div class="metric"><span>Next level</span><strong>'+progression.next_level+'</strong><small>'+progression.progress_percent+'% progress</small></div><div class="metric"><span>Current effect</span><strong>+'+progression.effect_percent.toFixed(1)+'%</strong><small>Player progression modifier</small></div></div><div class="bar"><i style="width:'+progression.progress_percent+'%"></i></div><div class="actions" style="margin-top:12px">'+actionButton('progression_advance','Advance player level','dark')+' <span class="badge">Server validates cost, prerequisites, and tier cap</span></div></div><div class="card wide"><div class="eyebrow">COMMAND ALERTS</div><h2>Events and warnings</h2>'+alerts+'</div><div class="card side-card"><div class="eyebrow">PAGE CONTRACT</div><h2>Dashboard / dashboard</h2><p class="permission">The browser submits player intent only. `process_turns` calls the PHP service layer, settles resources and queues in a transaction, writes an event, and returns refreshed state.</p><span class="badge">process_turns</span> <span class="badge">players</span> <span class="badge">player_resources</span> <span class="badge">rankings</span> <span class="badge">game_events</span></div></div>';document.querySelectorAll('.server-action').forEach(b=>b.onclick=()=>{const f=document.getElementById('feedback');f.style.display='block';f.textContent='Intent accepted: '+b.dataset.action+' → POST actions/game.php → permission check → transaction → refreshed dashboard state.'})}
function accountInfo(){const a=state.account||{commander:'Tanang',username:'tanang',race:"Tau'ri",government:'Stellar Republic',rank:'Commander',level:12,glory:1840,reputation:920,experience:72800,victories:38,defeats:7,protection:'Active',vacation:'Off',registration:'Complete',created:'2026-01-14',lastLogin:'Current session'};document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Account Information';document.getElementById('description').textContent='Commander identity, faction bonuses, progression, protection, and account security are read from authenticated server state.';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">COMMANDER PROFILE</div><h2>'+esc(a.commander)+' <span class="badge good">AUTHENTICATED</span></h2><div class="metric-grid"><div class="metric"><span>Username</span><strong>'+esc(a.username)+'</strong><small>Account handle</small></div><div class="metric"><span>Rank</span><strong>'+esc(a.rank)+'</strong><small>Level '+fmt(a.level)+'</small></div><div class="metric"><span>Registration</span><strong>'+esc(a.registration)+'</strong><small>Created '+esc(a.created)+'</small></div></div></div><div class="card side-card"><div class="eyebrow">FACTION IDENTITY</div><h2>'+esc(a.race)+'</h2><div class="row"><div><strong>Government</strong><small>Current political system</small></div><span class="badge">'+esc(a.government)+'</span></div><div class="row"><div><strong>Combined modifiers</strong><small>Race × government</small></div><span class="badge good">APPLIED</span></div><button class="button dark" onclick="openPage(\'race\')">Review faction bonuses</button></div><div class="card wide"><div class="eyebrow">PROGRESSION</div><h2>Glory, Reputation, and experience</h2><div class="metric-grid"><div class="metric"><span>Experience</span><strong>'+fmt(a.experience)+'</strong><small>Level '+fmt(a.level)+' progression</small><div class="bar"><i style="width:72%"></i></div></div><div class="metric"><span>Glory</span><strong>'+fmt(a.glory)+'</strong><small>Ascension resource</small></div><div class="metric"><span>Reputation</span><strong>'+fmt(a.reputation)+'</strong><small>Diplomacy and rank</small></div></div><div class="row"><span>Victories / defeats</span><strong>'+fmt(a.victories)+' / '+fmt(a.defeats)+'</strong></div></div><div class="card side-card"><div class="eyebrow">PROTECTION</div><h2>Account safeguards</h2><div class="row"><div><strong>Protection status</strong><small>Combat eligibility</small></div><span class="badge good">'+esc(a.protection)+'</span></div><div class="row"><div><strong>Vacation mode</strong><small>Long-term protection</small></div><span class="badge">'+esc(a.vacation)+'</span></div><button class="button" onclick="openPage(\'vacation\')">Manage vacation mode</button></div><div class="card wide"><div class="eyebrow">SECURITY AND SESSION</div><h2>Authenticated account state</h2><div class="row"><span>Last login</span><strong>'+esc(a.lastLogin)+'</strong></div><div class="row"><span>Session protection</span><span class="badge good">CSRF + RBAC ENABLED</span></div><div class="row"><span>Data authority</span><span class="badge good">SERVER-SIDE PDO</span></div><p class="permission">Read-only account data is scoped to the authenticated commander. Race changes, government reform, vacation, and ascension use separate CSRF-protected PHP actions.</p></div><div class="card side-card"><div class="eyebrow">ACCOUNT CONTROLS</div><h2>Sub-pages</h2><div class="actions"><button class="button" onclick="openPage(\'race\')">Race and government</button><button class="button" onclick="openPage(\'ascension\')">Progression and ascension</button><button class="button" onclick="openPage(\'messages\')">Account messages</button></div><div class="feedback" style="display:block">State loaded from players, races, governments, rankings, progression, glory, protection, and audit records.</div></div></div>'}function openPage(page){selected=page;render()}function economyPage(){const b=interactions.economy.buttons||{};const r=state.resources;const banked=Number(r.banked_naquadah||0);const controlRows=Object.entries(b).map(([label,x])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(x.logic)+'</small></div>'+actionButton(x.action,label,'dark')+'</div>').join('');document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Resources & Vault';document.getElementById('description').textContent='Resources & Vault — Validated server-side state transition';document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Resources & Vault</h2><div class="metric-grid"><div class="metric"><span>Available Naquadah</span><strong>'+fmt(r.naquadah)+'</strong><small>Spendable balance</small></div><div class="metric"><span>Protected vault</span><strong>'+fmt(banked)+'</strong><small>Banked Naquadah</small></div><div class="metric"><span>Dark Matter</span><strong>'+fmt(r.dark_matter)+'</strong><small>Special resource</small></div></div><div class="row"><span>Resource authority</span><span class="badge good">SERVER-VALIDATED</span></div><div class="row"><span>State transition</span><span class="badge">TRANSACTIONAL</span></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="actions">'+controlRows+'</div><p class="permission">authenticated commander</p></div><div class="card wide"><div class="eyebrow">RESOURCE RESERVES</div><h2>Eight-resource ledger</h2>'+Object.entries(r).map(([key,value])=>'<div class="row"><span>'+esc(key.replace('_',' '))+'</span><strong>'+fmt(value)+'</strong></div>').join('')+'</div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: deposit / withdraw</p><span class="badge">player_resources</span> <span class="badge">game_settings</span><p class="permission">Writes are transactional and guarded by authentication, CSRF, RBAC, ownership, cooldown, and resource validation.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','empty','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>'}function breakdownPage(){const b=interactions.breakdown.buttons||{};const inc=state.income||{};const formula=inc.formula||'settlement = (base production × race modifier × government modifier × technology) − upkeep';const base=Number(inc.base_production||0),raceModifier=Number(inc.race_modifier||1),governmentModifier=Number(inc.government_modifier||1),technologyModifier=Number(inc.technology_modifier||1),foodUpkeep=Number((inc.upkeep||{}).food||0),waterUpkeep=Number((inc.upkeep||{}).water||0),energyUpkeep=Number((inc.upkeep||{}).energy||0),gross=Number(inc.gross_output||0),net=Number(inc.net_settlement||0),colonies=inc.colonies||[],primary=colonies[0]||null,stateLabel=inc.state||'empty';const actionRows=Object.entries(b).map(([label,x])=>'<div class="action"><div><strong>'+esc(label)+'</strong><small>'+esc(x.logic)+'</small></div><button class="button income-intent" data-action="'+esc(x.action)+'">'+esc(label)+'</button></div>').join('');const states=['ready','empty','protected','error'];document.getElementById('section').textContent='COMMAND CENTER';document.getElementById('title').textContent='Income Breakdown';document.getElementById('description').textContent='Income Breakdown — '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">PAGE DETAILS</div><h2>Income Breakdown</h2><div class="metric-grid"><div class="metric"><span>Base income</span><strong>'+fmt(base)+'</strong><small>Per settlement cycle</small></div><div class="metric"><span>Gross settlement</span><strong>'+fmt(gross)+'</strong><small>Before life-support upkeep</small></div><div class="metric"><span>Net settlement</span><strong>'+fmt(net)+'</strong><small>After food, water, and energy</small></div></div><div class="row"><div><strong>Settlement formula</strong><small>'+formula+'</small></div><span class="badge good">SERVER MODEL</span></div></div><div class="card side-card"><div class="eyebrow">PAGE CONTROLS</div><h2>Buttons and forms</h2><div class="actions">'+actionRows+'</div><p class="permission">Authenticated commander · read-only scope · owned colonies only</p><div id="income-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">MODIFIER BREAKDOWN</div><h2>Race, government, and technology</h2><div class="row"><span>Tau’ri race modifier</span><strong>+'+Math.round((raceModifier-1)*100)+'%</strong></div><div class="row"><span>Stellar Republic economy modifier</span><strong>+'+Math.round((governmentModifier-1)*100)+'%</strong></div><div class="row"><span>Technology multiplier</span><strong>'+technologyModifier.toFixed(2)+'×</strong></div><div class="row"><span>Combined production multiplier</span><strong>'+((raceModifier*governmentModifier*technologyModifier).toFixed(3))+'×</strong></div></div><div class="card side-card"><div class="eyebrow">COLONY PRODUCTION</div><h2>Owned colony comparison</h2><div class="row"><div><strong>'+esc(primary?primary.name:'No owned colonies')+'</strong><small>'+esc(primary?((primary.coordinate||'No coordinate')+' · '+(primary.biome||'Unknown biome')):'Commander-owned colony scope is empty')+'</small></div><span class="badge '+(primary?'good':'')+'">'+(primary?'PRIMARY':'EMPTY')+'</span></div><div class="row"><span>Population workforce</span><strong>'+fmt(primary?primary.population:0)+'</strong></div><div class="row"><span>Colony portfolio</span><strong>'+fmt(inc.colony_count||colonies.length)+'</strong></div><button class="button income-intent" data-action="read_colony_comparison">Compare colonies</button></div><div class="card wide"><div class="eyebrow">FOOD, WATER, AND ENERGY UPKEEP</div><h2>Life-support costs per settlement</h2><div class="metric-grid"><div class="metric"><span>Food upkeep</span><strong>'+fmt(foodUpkeep)+'</strong><small>Population consumption</small></div><div class="metric"><span>Water upkeep</span><strong>'+fmt(waterUpkeep)+'</strong><small>Population consumption</small></div><div class="metric"><span>Energy upkeep</span><strong>'+fmt(energyUpkeep)+'</strong><small>Infrastructure reserve</small></div></div><div class="row"><span>Total upkeep</span><strong>'+fmt(foodUpkeep+waterUpkeep+energyUpkeep)+'</strong></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: read-only</p>'+['player_resources','player_colonies','races','government_types','technologies','universe_planets'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Read actions are authenticated, CSRF-protected, RBAC-checked, and scoped to commander-owned colonies.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+states.map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.income-intent').forEach(button=>button.onclick=()=>{const f=document.getElementById('income-feedback');f.style.display='block';f.textContent='Read-only intent accepted: '+button.dataset.action+' → ownership check → EconomyService calculation → refreshed settlement state.'})}function sabotagePage(){const c=state.covert||{};const targets=state.target_board||[];const formula='damage = bounded system disruption × success probability × covert technology';const rows=targets.map(t=>'<tr><td><strong>'+esc(t.name)+'</strong></td><td>'+esc(t.race)+'</td><td>#'+esc(t.rank)+'</td><td>'+fmt(t.defense)+'</td><td>'+fmt(t.covert)+'</td><td><span class="badge '+(t.status==='PROTECTED'?'':'good')+'">'+esc(t.status)+'</span></td><td><button class="button sabotage-intent" data-target="'+t.id+'" data-action="covert:sabotage" '+(t.status==='PROTECTED'?'disabled':'')+'>Sabotage</button></td></tr>').join('');const selected=targets.find(t=>t.status==='OPEN')||targets[0]||{id:0,name:'No target',covert:0,status:'PROTECTED'};const detection=Math.max(0,(Number(selected.covert)||0)-20-(Number(c.covert_level)||1));const success=Math.max(5,Math.min(95,100-detection));const damage=Math.max(1,Math.min(25,Math.round((Number(c.available_agents)||0)*0.10*(success/100)*(Number(c.covert_level)||1))));document.getElementById('section').textContent='ATTACK';document.getElementById('title').textContent='Sabotage Operations';document.getElementById('description').textContent='Target enemy systems with bounded sabotage damage and detection handling. '+formula;document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">COVERT OPERATIONS</div><h2>Sabotage mission</h2><div class="metric-grid"><div class="metric"><span>Available agents</span><strong>'+fmt(c.available_agents||0)+'</strong><small>Commander covert pool</small></div><div class="metric"><span>Detection formula</span><strong>− agents</strong><small>'+esc(formula.replace('damage = ','detection = defender counter-intelligence − attacker agents − covert technology; damage = '))+'</small></div><div class="metric"><span>Mission state</span><strong>'+esc(c.mission_state||'READY')+'</strong><small>Target and ownership validation required</small></div></div><div class="row"><span>Target intelligence</span><strong>Defense, resources, technology</strong></div><div class="row"><span>Detection handling</span><span class="badge">CLASSIFIED REPORT</span></div></div><div class="card side-card"><div class="eyebrow">MISSION CONTROLS</div><h2>Buttons and forms</h2><div class="actions"><div class="action"><div><strong>Run reconnaissance</strong><small>Generate low-risk target intelligence with detection calculation.</small></div><button class="button sabotage-intent" data-action="covert:recon" data-target="'+selected.id+'">Run reconnaissance</button></div><div class="action"><div><strong>Run spy mission</strong><small>Resolve spy mission and store report.</small></div><button class="button sabotage-intent" data-action="covert:spy" data-target="'+selected.id+'">Run spy mission</button></div><div class="action"><div><strong>Run sabotage</strong><small>Resolve sabotage with detection and damage caps.</small></div><button class="button dark sabotage-intent" data-action="covert:sabotage" data-target="'+selected.id+'" '+(selected.status==='PROTECTED'?'disabled':'')+'>Run sabotage</button></div></div><p class="permission">Authenticated commander · agents required · target ownership validated</p><div id="sabotage-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">TARGET SYSTEMS</div><h2>Known enemy systems</h2><table class="table"><thead><tr><th>Realm</th><th>Race</th><th>Rank</th><th>Defense</th><th>Counter-intelligence</th><th>Status</th><th>Operation</th></tr></thead><tbody>'+rows+'</tbody></table></div><div class="card side-card"><div class="eyebrow">SABOTAGE PREVIEW</div><h2>Bounded damage model</h2><div class="metric-grid"><div class="metric"><span>Selected target</span><strong>'+esc(selected.name)+'</strong><small>'+esc(selected.status)+'</small></div><div class="metric"><span>Detection score</span><strong>'+fmt(detection)+'</strong><small>Defender covert − agents − technology</small></div><div class="metric"><span>Success probability</span><strong>'+fmt(success)+'%</strong><small>Clamped server-side</small></div><div class="metric"><span>Damage cap</span><strong>'+fmt(damage)+'</strong><small>Bounded system disruption</small></div></div><div class="row"><span>Formula</span><span class="badge good">'+esc(formula)+'</span></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Attack contract</h2><p c