vel, update alert posture, and apply income or defense effects.</small></div><button class="button military-intent" data-action="set_defcon">Set DefCon</button></div><p class="permission">authenticated commander · server-side authority</p><div id="military-feedback" class="feedback"></div></div><div class="card wide"><div class="eyebrow">POWER BREAKDOWN</div><h2>Units and modifiers</h2><div class="row"><span>Attack base</span><strong>'+fmt(m.attack_base||0)+'</strong></div><div class="row"><span>Defense base</span><strong>'+fmt(m.defense_base||0)+'</strong></div><div class="row"><span>Covert base</span><strong>'+fmt(m.covert_base||0)+'</strong></div><div class="row"><span>Anti-covert base</span><strong>'+fmt(m.anti_covert_base||0)+'</strong></div><div class="row"><span>Faction modifiers</span><span class="badge good">'+esc(m.race_name||'Race')+' × '+esc(m.government_name||'Government')+'</span></div></div><div class="card side-card"><div class="eyebrow">READINESS</div><h2>Operational status</h2><div class="metric-grid">'+metric('Readiness',(m.readiness||0)+'%','Attack turns available: '+fmt(m.attack_turns||0))+metric('Attack turns',m.attack_turns||0,'Available offensive operations')+'</div><div class="bar"><i style="width:'+Math.min(100,Math.max(0,Number(m.readiness||0)))+'%"></i></div><p class="permission">Readiness is derived from available attack turns and validated server state.</p></div><div class="card wide"><div class="eyebrow">DEFCON STATE</div><h2>Alert posture</h2><div class="metric-grid">'+metric('Current DefCon',m.defcon_level??s.level??0,'0 = standard posture · 4 = maximum defense')+metric('Cooldown state',m.cooldown_state||s.cooldown_state||'ready',fmt(m.cooldown_remaining_seconds||s.cooldown_remaining_seconds||0)+' seconds remaining')+metric('Server action','set_defcon','Transactional resource and state update')+'</div><div class="row"><span>DefCon effect</span><span class="badge">Defense posture applied server-side</span></div></div><div class="card side-card"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: read_military_stats / set_defcon</p>'+['player_resources','player_unit_stats','rankings','protection_states','players','game_events'].map(x=>'<span class="badge">'+x+'</span> ').join('')+'<p class="permission">Read values are authenticated. DefCon changes lock state, validate level and cooldown, update the player, write an event, and commit atomically.</p></div><div class="card wide"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','cooldown','invalid-input','success','error'].map(x=>'<div class="row"><span>'+x+'</span><span class="badge">HANDLED</span></div>').join('')+'</div></div>';document.querySelectorAll('.military-intent').forEach(button=>button.onclick=()=>{const f=document.getElementById('military-feedback');f.style.display='block';f.textContent='Intent accepted: '+button.dataset.action+' → authentication → RBAC → validation → transactional GameService response.'})}function explorationPage(){const x=state.mothership_exploration||{};const m=x.mothership||{};const rows=(x.expeditions||[]).map(p=>'<tr><td><strong>'+esc(p.name)+'</strong><small>'+esc(p.coordinate_label||'')+' · '+esc(p.biome||'')+'</small></td><td>'+fmt(p.distance)+'</td><td>'+fmt(p.ship_science)+'</td><td>'+Number(p.biome_rarity||1).toFixed(2)+'×</td><td>'+fmt(p.estimated_yield)+'</td><td>'+fmt(p.travel_seconds)+'s</td><td>'+Math.round(Number(p.discovery_risk||0)*100)+'%</td><td><form method="post" action="actions/game.php">'+(state.csrf||'')+'<input type="hidden" name="action" value="explore"><input type="hidden" name="redirect" value="exploration"><input type="hidden" name="universe_planet_id" value="'+fmt(p.id)+'"><button class="button dark" type="submit">Explore</button></form></td></tr>').join('');document.getElementById('section').textContent='MOTHERSHIP';document.getElementById('title').textContent='Exploration';document.getElementById('description').textContent='Exploration — '+(x.formula||'exploration yield = distance × ship science × biome rarity');document.getElementById('content').innerHTML='<div class="cc-grid"><div class="card wide"><div class="eyebrow">EXPLORATION MODEL</div><h2>Available expeditions</h2><p class="permission">'+esc(x.formula||'exploration yield = distance × ship science × biome rarity')+'</p><div class="metric-grid"><div class="metric"><span>Ship science</span><strong>'+fmt(m.ship_science||0)+'</strong><small>Exploration level + hangar science</small></div><div class="metric"><span>Hull readiness</span><strong>'+(m.ready?'READY':'LOCKED')+'</strong><small>Commander-owned mothership</small></div><div class="metric"><span>Targets</span><strong>'+fmt((x.expeditions||[]).length)+'</strong><small>Unoccupied universe planets</small></div></div></div><div class="card side-card"><div class="eyebrow">MISSION CONTROLS</div><h2>Dispatch rules</h2><div class="row"><span>Target validation</span><span class="badge good">REQUIRED</span></div><div class="row"><span>Operation cost</span><strong>25,000 N</strong></div><div class="row"><span>Cooldown</span><span class="badge">SERVER LOCK</span></div><p class="permission">Authenticated commander · mothership ownership · hull readiness · resource validation · transactional result</p></div><div class="card wide"><div class="eyebrow">UNIVERSE TARGET BOARD</div><h2>Distance, rarity, and risk</h2><table class="table"><thead><tr><th>Planet</th><th>Distance</th><th>Science</th><th>Biome rarity</th><th>Yield</th><th>Travel</th><th>Risk</th><th>Action</th></tr></thead><tbody>'+(rows||'<tr><td colspan="8">No unoccupied exploration targets available.</td></tr>')+'</tbody></table></div><div class="card side-card"><div class="eyebrow">FEEDBACK STATES</div><h2>Result handling</h2>'+['ready','protected','insufficient-resource','cooldown','success','error'].map(s=>'<div class="row"><span>'+s+'</span><span class="badge">HANDLED</span></div>').join('')+'</div><div class="card wide"><div class="eyebrow">SERVER ACTIONS / DATABASE</div><h2>Backend contract</h2><p class="permission">Action: explore</p>'+['motherships','planet_explorations','universe_solar_systems','universe_planets','player_resources','player_cooldowns','game_events'].map(t=>'<span class="badge">'+t+'</span> ').join('')+'<p class="permission">Yield is calculated and persisted server-side. Client controls submit only the selected universe planet identifier.</p></div></div>'}function render(){const feedback=state.feedback||{};let banner=document.getElementById('global-feedback');if(!banner){banner=document.createElement('div');banner.id='global-feedback';banner.className='feedback';document.getElementById('content').before(banner)}banner.textContent=feedback.message||'';banner.dataset.state=feedback.state||'ready';banner.style.display=feedback.message?'block':'none';renderNav((document.getElementById('search').value||'').toLowerCase().trim());if(selected==='dashboard')commandCenter();else if(selected==='account-info')accountInfo();else if(selected==='resources')economyPage();else if(selected==='income')breakdownPage();else if(selected==='military-stats')militaryStatsPage();else if(selected==='sabotage')sabotagePage();else if(selected==='attack-log')reportsPage();else if(selected==='weapons')weaponsPage();else if(selected==='weapon-market')weaponMarketPage();else if(selected==='tech-defense')defenseTechnologyPage();else if(selected==='repair')weaponRepairPage();else if(selected==='units'||selected==='training')unitTrainingPage();else if(selected==='miners')workforcePage();else if(selected==='super-units')superUnitsPage();else if(selected==='unit-production')unitProductionPage();else if(selected==='technology')technologyTreePage();else if(selected==='tech-offense')offenseTechnologyPage();else if(selected==='tech-covert')covertTechnologyPage();else if(selected==='tech-anti-covert')antiCovertTechnologyPage();else if(selected==='spy-log')spyLogPage();else if(selected==='enemy-intelligence')enemyIntelligencePage();else if(selected==='race')racePage();else if(selected==='exploration')explorationPage();else if(['targets','spy'].includes(selected))attackPage(selected);else genericPage()};document.getElementById('search').oninput=()=>render();render();
</script></body></html>
